from accelerator import staging_columns  # noqa: E402

FAILURES: list[str] = []


def check(name: str, condition: bool, detail: str = "") -> None:
    if condition:
        print(f"  PASS  {name}")
    else:
        print(f"  FAIL  {name} {detail}")
        FAILURES.append(name)


def _raises(fn) -> bool:
    """True if fn raises anything -- the general-purpose sibling of _audit_raises,
    for rule functions (invoice_rules and friends) that are not spec/SpecError-specific."""
    try:
        fn()
    except Exception:  # noqa: BLE001
        return True
    return False


def _refusal_message(fn) -> str:
    """The text of the SpecError fn raises -- for asserting the message is actionable."""
    try:
        fn()
    except spec.SpecError as exc:
        return str(exc)
    return ""


def _audit_raises(fn) -> bool:
    """True if fn raises anything -- for asserting a guard rejects rather than escapes."""
    try:
        fn()
    except Exception:  # noqa: BLE001
        return True
    return False


def expect_error(name: str, fn, fragment: str) -> None:
    try:
        fn()
    except spec.SpecError as exc:
        if fragment.lower() in str(exc).lower():
            print(f"  PASS  {name}")
        else:
            print(f"  FAIL  {name} -- wrong message: {exc}")
            FAILURES.append(name)
    except Exception as exc:  # noqa: BLE001
        print(f"  FAIL  {name} -- wrong exception type {type(exc).__name__}: {exc}")
        FAILURES.append(name)
    else:
        print(f"  FAIL  {name} -- no error raised")
        FAILURES.append(name)


# --------------------------------------------------------------------------- #
print("\n== hash rulebook: golden expressions (change = re-key the estate) ==")

GOLDEN_SINGLE = (
    "UNHEX(SHA2(COALESCE(NULLIF(UPPER(TRIM(CAST(reference_code AS STRING))), ''), '^^'), 256))"
)
check(
    "authored single-column key is stable",
    hashing.hash_key(["reference_code"]) == GOLDEN_SINGLE,
    f"\n        got {hashing.hash_key(['reference_code'])}",
)

federated = hashing.hash_key(["reference_code"], source_scope="striive_eu")
check("federated key upper-cases the scope literal", "'STRIIVE_EU'" in federated)
check("federated key differs from authored key", federated != GOLDEN_SINGLE)
check("federated key uses the rulebook delimiter", "CONCAT_WS('||'" in federated)

check(
    "null and empty string collapse to the same token",
    hashing.normalise("x").count("'^^'") == 1,
)
check(
    "hashdiff right-trims trailing null tokens so appended columns do not re-key",
    "REGEXP_REPLACE" in hashing.hashdiff(["a", "b"]),
)
check(
    "hashdiff of a reordered payload is a DIFFERENT expression",
    hashing.hashdiff(["a", "b"]) != hashing.hashdiff(["b", "a"]),
)
check("key type is BINARY for sha2_256", hashing.key_type_sql() == "BINARY")
check("zero key is 32 zero bytes", hashing.zero_key_sql() == f"UNHEX('{'00' * 32}')")
check(
    "rulebook version is stamped for table properties",
    hashing.rulebook_properties()["hfig.hash.rulebook_version"] == hashing.RULEBOOK_VERSION,
)

try:
    hashing.hash_key([])
    check("empty column list is rejected", False)
except hashing.RulebookError:
    check("empty column list is rejected", True)


