print("\n== validation guards: bad metadata must fail the build ==")


def write(body: str) -> Path:
    d = Path(tempfile.mkdtemp())
    p = d / "bad.yml"
    p.write_text(body, encoding="utf-8")
    return p


expect_error(
    "hub carrying descriptive attributes is rejected",
    lambda: spec.load_entity(write(
        "name: thing\nkind: hub\ndomain: d\nbusiness_keys: [k]\npayload: [title]\n"
        "sources:\n  - {name: S, bronze_table: b, key_columns: [k]}\n"
    )),
    "carries the business key and nothing else",
)

