print("\n== hashdiff case sensitivity (a correction IS a change) ==")
check(
    "payload is NOT case-folded by default",
    "UPPER(" not in hashing.hashdiff(["job_title"]),
    "\n        " + hashing.hashdiff(["job_title"]),
)
check(
    "business keys ARE case-folded",
    "UPPER(" in hashing.hash_key(["reference_code"]),
)
check(
    "a case correction changes the hashdiff",
    hashing.reference_hashdiff(["Senior Java Developer"])
    != hashing.reference_hashdiff(["senior java developer"]),
)
check(
    "a case difference does NOT change a business key",
    hashing.reference_key(["str-2026-00912"]) == hashing.reference_key(["STR-2026-00912"]),
)


print("\n== golden hash vectors: the reference implementation is pinned ==")
import json  # noqa: E402

vectors = json.loads((ROOT / "tests" / "golden_hash_vectors.json").read_text())

check(
    "vectors were generated under the current rulebook",
    vectors["rulebook"]["algorithm"] == hashing.ALGORITHM
    and vectors["rulebook"]["version"] == hashing.RULEBOOK_VERSION
    and vectors["rulebook"]["hashdiff_uppercase"] == hashing.HASHDIFF_UPPERCASE,
)
check("algorithm is the ratified one", hashing.ALGORITHM == hashing.ALGORITHM_RATIFIED)

key_drift = [
    c["name"]
    for c in vectors["keys"]
    if hashing.reference_key(c["values"], source_scope=c["source_scope"]) != c["sha256_hex"]
]
check("every golden business key still reproduces", not key_drift, f"drifted: {key_drift}")

hd_drift = [
    c["name"]
    for c in vectors["hashdiffs"]
    if hashing.reference_hashdiff(c["values"]) != c["sha256_hex"]
]
check("every golden hashdiff still reproduces", not hd_drift, f"drifted: {hd_drift}")

_by = {c["name"]: c["sha256_hex"] for c in vectors["hashdiffs"]}
check(
    "appending a null column does not change the hashdiff",
    _by["baseline"] == _by["appended_null_column"] == _by["appended_two_null_columns"],
)
check("appending a populated column does change it", _by["baseline"] != _by["appended_populated_column"])
check("reordering the payload changes it", _by["baseline"] != _by["reordered_payload"])
check("a case correction changes it", _by["baseline"] != _by["case_correction"])

_k = {c["name"]: c["sha256_hex"] for c in vectors["keys"]}
check("whitespace and case noise in a key is normalised away",
      _k["federated_striive_job"] == _k["case_and_whitespace_noise"])
check("NULL and blank key components collapse together",
      _k["null_key_component"] == _k["blank_key_component"])
check("the same real job from two sources gets two different keys",
      _k["federated_striive_job"] != _k["federated_bullhorn_job"])
check("an authored key is not source-scoped",
      "||" not in next(c["pre_hash_string"] for c in vectors["keys"] if c["name"] == "authored_client"))


print("\n== key-component safety: collisions quarantine, never resolve silently ==")
rules = hashing.key_safety_rules(["reference_code"])
check("a NULL key component is rejected", "key_present_reference_code" in rules)
check("a blank key component is rejected", "TRIM" in rules["key_present_reference_code"])
check("a key containing the delimiter is rejected",
      "key_no_delimiter_reference_code" in rules)
check("the delimiter rule references the rulebook delimiter",
      f"'{hashing.DELIMITER}'" in rules["key_no_delimiter_reference_code"])
check("a key equal to the null token is rejected",
      "key_not_null_token_reference_code" in rules)
check("delimiter rule is null-safe (NULL must not evaluate to NULL)",
      "COALESCE" in rules["key_no_delimiter_reference_code"])
check("optional composite components can skip the presence rule",
      "key_present_x" not in hashing.key_safety_rules(["x"], mandatory=False))
check("multi-column keys produce rules per component",
      len(hashing.key_safety_rules(["a", "b"])) == 6)

# the collision the rules exist to prevent
collide_a = hashing.reference_payload_key(["AB", "C"])
collide_b = hashing.reference_payload_key(["A", "BC"])
check("plain components do not collide", collide_a != collide_b,
      f"{collide_a!r} vs {collide_b!r}")
embedded = hashing.reference_payload_key(["A||B", "C"])
shifted = hashing.reference_payload_key(["A", "B||C"])
check("an EMBEDDED delimiter WOULD collide -- which is why it is quarantined",
      embedded == shifted, f"{embedded!r} vs {shifted!r}")

check("hashdiff case handling is ratified, not a knob",
      hashing.HASHDIFF_UPPERCASE == hashing.HASHDIFF_UPPERCASE_RATIFIED is False)


