print("\n== accounting roles: the journal gate reads its column names from metadata ==")

_ACCT = """
name: general_journal_line
kind: nhl
domain: finance
parents: [accounting_journal, organisation]
transaction_key: [seqnumbr]
payload: [debitamt, crdtamnt]
accounting:
  journal: accounting_journal
  debit: debitamt
  credit: crdtamnt
  line_order: seqnumbr
sources:
  - name: GP_US
    bronze_table: 01_usnc_bronze_dev.great_plains_raw.gl20000
    parent_keys:
      accounting_journal: [jrnentry]
      organisation: [input_db]
"""
_a = spec.load_entity(write(_ACCT))
check("accounting roles are parsed onto the entity",
      _a.accounting_map == {"journal": "accounting_journal", "debit": "debitamt",
                            "credit": "crdtamnt", "line_order": "seqnumbr"},
      f"got {_a.accounting_map!r}")
check("line_order is optional",
      spec.load_entity(write(_ACCT.replace("  line_order: seqnumbr\n", ""))).accounting_map
      == {"journal": "accounting_journal", "debit": "debitamt", "credit": "crdtamnt"})
expect_error(
    "an unknown accounting role is refused -- it would leave the gate asserting nothing",
    lambda: spec.load_entity(write(_ACCT.replace("  debit: debitamt", "  debits: debitamt"))),
    "unknown role",
)
expect_error(
    "declaring one side of the balance without the other is refused",
    lambda: spec.load_entity(write(_ACCT.replace("  credit: crdtamnt\n", ""))),
    "only one of debit/credit",
)
expect_error(
    "declaring amounts without saying what groups them into a journal is refused",
    lambda: spec.load_entity(write(_ACCT.replace("  journal: accounting_journal\n", ""))),
    "no journal role",
)
expect_error(
    "a journal role naming something that is not a parent is refused",
    lambda: spec.load_entity(write(_ACCT.replace("  journal: accounting_journal",
                                                 "  journal: ledger_account"))),
    "not one of this entity's parents",
)
expect_error(
    "a role naming a column the entity does not carry is refused",
    lambda: spec.load_entity(write(_ACCT.replace("  debit: debitamt",
                                                 "  debit: debit_amount"))),
    "not in this entity's payload",
)
expect_error(
    "a control total that is not in the declaring entity's payload is refused",
    lambda: spec.load_entity(write(
        _ACCT.replace("  line_order: seqnumbr", "  control_total: control_total_amount"))),
    "control_total",
)

