print("\n== Vault object versioning: physical and stable names ==")

def _round_trips(base: str, version: int) -> bool:
    """True if physical() -> stable() returns the original base.

    GUARDED, because stable() raises by design: an exception inside a check
    CONDITION aborts the whole suite, which is strictly worse than one red check.
    A broken physical() must turn this RED, not silence everything after it.
    """
    try:
        return naming.stable(naming.physical(base, version)) == base
    except Exception:
        return False

check("version 1 is suffixed like every other version",
      naming.physical("hub_invoice", 1) == "hub_invoice_rev1",
      "v1 is NOT special. If v1 were unsuffixed, the unversioned name would be a TABLE "
      "today and a VIEW after the first v2, and every consumer would have to know which")
check("a later version differs only in the suffix",
      naming.physical("hub_invoice", 2) == "hub_invoice_rev2")
check("the SOURCE suffix comes first, the VERSION suffix last",
      naming.physical("sat_invoice_header_fieldglass_us", 1)
      == "sat_invoice_header_fieldglass_us_rev1",
      "a satellite is one table per source; version qualifies the whole table, so it is "
      "outermost. The other order would sort two versions of one satellite apart")
check("stable() is the exact inverse of physical()",
      all(_round_trips(t, v)
          for t in ("hub_invoice", "sat_invoice_header_fieldglass_us", "nhl_journal_line")
          for v in (1, 2, 17)),
      "the view name is derived from the table name and back; if the round trip is not "
      "exact, a cutover repoints the wrong view")
check("stable() REFUSES a name with no version suffix",
      _raises(lambda: naming.stable("hub_invoice")),
      "returning the input unchanged would make an unmigrated table look like a view "
      "name and the migration look finished")
check("stable() refuses a name whose suffix is not a number",
      _raises(lambda: naming.stable("hub_invoice_revtwo")))

print("\n== Vault object versioning: tables() and stable_tables() ==")

_m_ver = spec.load_model("metadata/entities")
_hub_inv = next(e for e in _m_ver.entities if e.name == "invoice")
_sat_hdr = next(e for e in _m_ver.entities if e.name == "invoice_header")

check("a hub's physical table carries its version",
      [t for _s, t in _hub_inv.tables()] == ["hub_invoice_rev1"])
check("a hub's stable view name is unversioned",
      [t for _s, t in _hub_inv.stable_tables()] == ["hub_invoice"])
check("a satellite keeps one table per source AND gains a version",
      [t for _s, t in _sat_hdr.tables()] == ["sat_invoice_header_fieldglass_us_rev1"])
check("a satellite's stable view keeps the source, drops the version",
      [t for _s, t in _sat_hdr.stable_tables()] == ["sat_invoice_header_fieldglass_us"])
check("tables() and stable_tables() agree one for one, in order",
      all(len(e.tables()) == len(e.stable_tables()) for e in _m_ver.entities)
      and all(naming.stable(p) == s
              for e in _m_ver.entities
              for (_sp, p), (_ss, s) in zip(e.tables(), e.stable_tables())),
      "a view must exist for exactly one table and a cutover repoints by position; if "
      "these two lists ever disagree, a cutover points a view at another object")
check("no two entities in the model claim the same stable view name",
      len({s for e in _m_ver.entities for _x, s in e.stable_tables()})
      == sum(len(e.stable_tables()) for e in _m_ver.entities),
      "two entities sharing a view name would have the second silently replace the "
      "first's view, and the loser would keep loading a table nobody reads")

