def _child_with(n_cols):
    """An NHL whose binding declares n_cols columns for the literal-free parent hub."""
    binding = spec.SourceBinding(
        name="S", bronze_table="b", key_columns=("t",),
        parent_keys=((_lf.name, tuple(f"c{i}" for i in range(n_cols))),))
    entity = spec.Entity(
        name="probe_child", kind="nhl", domain="d", key_style="authored",
        transaction_key=("t",), parents=(_lf.name,), sources=(binding,))
    return entity, binding


_bad_e, _bad_s = _child_with(_n_keys + 1)
