_layer_pairs = {kind: [(e, t) for e, t in _ls.staged_satellites(_am)
                       if e.kind in _ls.kinds_for_layer(kind)]
               for kind in ("raw", "business")}
check("filtering staged_satellites by --layer=business keeps only csat entities",
      _layer_pairs["business"] and all(e.kind == "csat" for e, _t in _layer_pairs["business"]),
      str(sorted(t for _e, t in _layer_pairs["business"])))
