# --------------------------------------------------------------------------- #
print("\n== C2: the completeness gate at its real position in the graph ==")

# The gate asserted closure as a FAILURE while sitting AHEAD of the task that writes the
# 'completed' row, so it was red by construction on every run. Reproduced below with the
# exact state the controller measured at its position in the graph
# (assert_mask_survival -> assert_audit_completeness -> publish_model_metadata):
#
#     runs  = [('RUN1', 'opened')]                      # written by create_control_objects
#     loads = [('RUN1', 'hub_accounting_journal')]      # written by the loaders
#
# These checks RUN main() against a Spark stand-in rather than reading its source, so
# "this run now reaches green" is measured, and "an unattributed discard still fails" is
# measured with it.


class _FakeAuditSpark:
    def __init__(self, runs, loads, discards):
        self.runs, self.loads, self.discards = runs, loads, discards
        self.queries: list[str] = []

    def sql(self, text):
        self.queries.append(" ".join(text.split()))
        # THE FAKE HONOURS A WHERE CLAUSE. It would be easier to ignore one -- and then a
        # gate narrowed back to a single run would still look as if it asserted over the
        # prior runs, which is the shape of defect this whole block exists to detect.
        _m = re.search(r"job_run_id = '([^']*)'", text)
        _only = _m.group(1) if _m else None

        def _keep(rows):
            return [r for r in rows if _only is None or r[0] == _only]

        # aud_table_discard BEFORE aud_table_load: the discard query's text does not
        # contain the load table's name, but testing in the other order would still be a
        # trap worth not setting.
        if "aud_table_discard" in text:
            return _FakeResult([{"job_run_id": r, "table_name": t, "discarded": d}
                                for r, t, d in _keep(self.discards)])
        if "aud_table_load" in text:
            return _FakeResult([{"job_run_id": r, "table_name": t,
                                 "staged": st, "accepted": a}
                                for r, t, st, a in _keep(self.loads)])
        if "aud_load_run" in text:
            return _FakeResult([{"job_run_id": r, "phase": ph}
                                for r, ph in _keep(self.runs)])
        raise AssertionError(f"the fake was asked an unexpected query: {text[:80]!r}")


def _run_audit_gate(fake, job_run_id=None):
    """main() with a Spark stand-in. Returns (exit code, captured output)."""
    _saved_argv, _saved_session = sys.argv, getattr(_stub_sql, "SparkSession", None)
    _stub_sql.SparkSession = types.SimpleNamespace(
        builder=types.SimpleNamespace(getOrCreate=lambda: fake))
    sys.argv = ["audit_completeness_check.py", "--catalog", "c",
                "--control-schema", "control"]
    if job_run_id is not None:
        sys.argv += ["--job-run-id", job_run_id]
    _buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(_buf):
            rc = _ac.main()
    finally:
        sys.argv, _stub_sql.SparkSession = _saved_argv, _saved_session
    return rc, _buf.getvalue()


_C2_STATE = _FakeAuditSpark(runs=[("RUN1", "opened")],
                            loads=[("RUN1", "hub_accounting_journal", 100, 100)],
                            discards=[])
_c2_rc, _c2_out = _run_audit_gate(_C2_STATE, job_run_id="RUN1")
check("C2: the gate PASSES on the exact in-flight state it sees in the graph",
      _c2_rc == 0,
      f"rc={_c2_rc} -- the 'completed' row is written by publish_model_metadata, which "
      f"DEPENDS on this gate, so as a hard assertion this was unsatisfiable:\n{_c2_out}")
check("C2: and the in-flight run is not reported as an anomaly either",
      "NOT CLOSED" not in _c2_out and "unclosed_prior_runs=0" in _c2_out,
      f"expected state announced as a finding on every run is how a report stops being "
      f"read:\n{_c2_out}")
_c2_noflag_rc, _c2_noflag_out = _run_audit_gate(
    _FakeAuditSpark([("RUN1", "opened")], [("RUN1", "hub_x", 5, 5)], []))
check("C2: without --job-run-id the in-flight run is REPORTED but still not failed",
      _c2_noflag_rc == 0 and "NOT CLOSED" in _c2_noflag_out
      and "unclosed_prior_runs=1" in _c2_noflag_out,
      f"rc={_c2_noflag_rc} -- closure is an observation now, in every invocation:\n"
      f"{_c2_noflag_out}")

# The HARD half must still be hard, and must still cover the in-flight run.
_c2_gap_rc, _c2_gap_out = _run_audit_gate(
    _FakeAuditSpark([("RUN1", "opened")],
                    [("RUN1", "hub_accounting_journal", 100, 59)],
                    [("RUN1", "hub_accounting_journal", 30)]), job_run_id="RUN1")
check("C2: an unattributed discard in the IN-FLIGHT run still FAILS the gate",
      _c2_gap_rc == 1 and "11 unaccounted" in _c2_gap_out,
      f"rc={_c2_gap_rc} -- the arithmetic is a property of the run's own rows and stays a "
      f"hard assertion:\n{_c2_gap_out}")
# ... and a PRIOR run's gap too. This is what proves --job-run-id did not quietly become a
# WHERE clause when the flag started being passed: the fake above honours one, so a
# narrowed query hides RUN0's gap and this check goes red.
_c2_prior_rc, _c2_prior_out = _run_audit_gate(
    _FakeAuditSpark([("RUN0", "opened"), ("RUN0", "completed"), ("RUN1", "opened")],
                    [("RUN0", "hub_x", 50, 20), ("RUN1", "hub_x", 5, 5)],
                    [("RUN0", "hub_x", 10)]), job_run_id="RUN1")
check("C2: an unattributed discard in a PRIOR run also still FAILS the gate",
      _c2_prior_rc == 1 and "run RUN0" in _c2_prior_out,
      f"rc={_c2_prior_rc} -- --job-run-id names the in-flight run for the CLOSURE report "
      f"only; it must not become a WHERE clause that narrows the hard assertion:\n"
      f"{_c2_prior_out}")
_c2_where = [q for q in _C2_STATE.queries if "WHERE" in q.upper()]
check("C2: none of the three queries carries a WHERE clause",
      not _c2_where,
      f"{_c2_where} -- every run on record is in scope for the arithmetic")

# A genuinely dead PRIOR run is reported by name, and does not block the run after it.
_c2_dead_rc, _c2_dead_out = _run_audit_gate(
    _FakeAuditSpark([("RUN0", "opened"), ("RUN1", "opened")],
                    [("RUN0", "hub_x", 5, 5), ("RUN1", "hub_x", 5, 5)], []),
    job_run_id="RUN1")
check("C2: a dead PRIOR run is reported by name and does NOT block this run",
      _c2_dead_rc == 0 and "run RUN0" in _c2_dead_out
      and "unclosed_prior_runs=1" in _c2_dead_out,
      f"rc={_c2_dead_rc} -- aud_load_run is append-only, so RUN0's missing 'completed' "
      f"row can never be supplied: as a hard gate this would be red for ever after, and "
      f"an unclearable gate gets switched off:\n{_c2_dead_out}")

# The predicate itself, directly -- pure, both directions, in-flight exclusion included.
check("C2: unclosed_runs excludes the in-flight run it is handed",
      _ac.unclosed_runs([("1", "opened")], [("1", "hub_x")], in_flight="1") == [],
      "the run whose closure is written by the NEXT task is expected state, not a finding")
check("C2: and still reports a DIFFERENT unclosed run in the same call",
      len(_ac.unclosed_runs([("1", "opened"), ("2", "opened"), ("2", "completed")],
                            [("1", "hub_x"), ("2", "hub_y")], in_flight="2")) == 1
      and "run 1" in _ac.unclosed_runs(
          [("1", "opened"), ("2", "opened"), ("2", "completed")],
          [("1", "hub_x"), ("2", "hub_y")], in_flight="2")[0],
      "excluding the in-flight run must not amount to excluding everything")
check("C2: unbalanced_tables has no notion of an in-flight run at all",
      "in_flight" not in inspect.signature(_ac.unbalanced_tables).parameters,
      "the arithmetic covers every run unconditionally -- a parameter that could narrow "
      "it is a parameter that eventually will")


# --------------------------------------------------------------------------- #
print("\n== C3: a retry must not write a second, wrong audit row ==")

# A Databricks repair run reuses the same {{job.run_id}}, and both loaders loop over every
# target exiting 1 only at the end -- so a table that already succeeded is re-processed on
# the retry. The vault insert adds nothing (NOT EXISTS for a hub, the hashdiff compare for
# a satellite), but the audit INSERT wrote a SECOND aud_table_load row for the same
# (run, table) with accepted = 0, plus a duplicate discard set. unbalanced_tables sums
# every discard row per (run, table) while iterating each LOAD row, so BOTH rows then
# report a gap -- and aud_table_load is append-only, so the completeness gate stays red.

check("C3: the writer offers an existence probe for (run, table)",
      "SELECT count(*)" in _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub_x")
      and "job_run_id = '42'" in _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub_x")
      and "table_name = 'hub_x'" in _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub_x"),
      "the guard is (run, table): keyed on the run alone it would skip every table after "
      "the first, and on the table alone it would never audit a second run")
check("C3: it probes aud_table_load, the table the duplicate would land in",
      "aud_table_load" in _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub_x")
      and "aud_table_discard" not in _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub_x"),
      "the load row is the one unbalanced_tables iterates")
check("C3: and it refuses a quote in either key rather than escaping it",
      _audit_raises(lambda: _audit.table_load_exists_sql(
          "c", "control", job_run_id="4'2", table_name="hub_x"))
      and _audit_raises(lambda: _audit.table_load_exists_sql(
          "c", "control", job_run_id="42", table_name="hub'x")),
      "a probe whose WHERE clause can be closed reads back the wrong count, which is "
      "worse than failing: it would skip an audit that was never written")

# STRUCTURE, NOT SUBSTRING. `table_load_exists_sql(` appearing before `table_load_sql(`
# is satisfied by a probe whose result is thrown away. This asserts that EVERY audit write
# in each loader sits inside a branch whose test reads the probe's result -- so hoisting
# the writes out of the guard, or ignoring the count, fails the check.
_AUDIT_WRITES = ("audit.table_load_sql", "audit.table_discard_sql")


def _audit_writes_under_retry_guard(path):
    """(audit writes in the file, of which are branch-guarded on the existence probe)."""
    _tree = ast.parse(path.read_text(encoding="utf-8"))

    def _writes(nodes):
        return [ast.unparse(sub.func) for n in nodes for sub in ast.walk(n)
                if isinstance(sub, ast.Call) and ast.unparse(sub.func) in _AUDIT_WRITES]

    _probe_vars = {t.id for n in ast.walk(_tree) if isinstance(n, ast.Assign)
                   for t in n.targets if isinstance(t, ast.Name)
                   and "table_load_exists_sql" in ast.unparse(n.value)}
    _guarded = [n for n in ast.walk(_tree) if isinstance(n, ast.If)
                and _probe_vars & {x.id for x in ast.walk(n.test)
                                   if isinstance(x, ast.Name)}]
    return len(_writes([_tree])), len(_writes([b for g in _guarded
                                              for b in g.body + g.orelse]))


for _loader in ("load_hubs.py", "load_satellites.py"):
    _total, _under = _audit_writes_under_retry_guard(ROOT / "checks" / _loader)
    check(f"C3: every audit write in {_loader} is branch-guarded on the probe",
          _total > 0 and _under == _total,
          f"{_under} of {_total} audit write(s) sit inside a branch that reads the "
          f"existence probe -- an unguarded one writes a second row on a repair run")

# BEHAVIOUR, not structure: run the real hub loader TWICE with the same job run id against
# a Spark stand-in, and count the audit INSERTs that came out. This is the check that would
# have caught the defect, because the defect is what happens on the second pass.
_FQ3 = re.compile(r"`[^`]+`\.`[^`]+`\.`([^`]+)`")


class _FakeHubSpark:
    """Simulates a hub load: the anti-join lands the distinct keys, and only once."""

    def __init__(self, staged=10, distinct=8):
        self.staged, self.distinct = staged, distinct
        self.hub_rows: dict = {}
        self.aud_load: list = []
        self.aud_discard: list = []
        # Task 6: the stable view, keyed by the NAME THE VIEW IS CREATED UNDER (the
        # unversioned name -- _FQ3 captures the FIRST fully-qualified name in the
        # statement, and in `CREATE OR REPLACE VIEW <stable> AS SELECT * FROM <hub>`
        # that is the view being created, not its source).
        self.views_created: list = []
        # F2: what information_schema.views reports for a stable name BEFORE this run,
        # {stable_name: view_definition}. Absent means the view does not exist yet
        # (bootstrap). A test sets this to simulate "already points elsewhere" -- the
        # one state the loader must leave untouched.
        self.existing_views: dict = {}
        # Task 3: what the pre-insert ambiguity probe returns for a LOG,
        # {stg_table: [row dict, ...]}. EMPTY BY DEFAULT, which is the measured state of
        # ten of the eleven hub logs and -- once the probe's DISTINCT has collapsed its
        # 5,266 exact-duplicate groups -- of the eleventh too. A test seeds it to
        # simulate a log whose tied rows genuinely disagree, which is the one state the
        # loader must refuse rather than guess at.
        self.ambiguous_rows: dict = {}
        # Which LOGS the ambiguity probe was actually run against, in order.
        self.probes: list = []
        # FINDING 1 / 29 September: what the loader ALTERed a mask onto, as
        # (table, column) in issue order, and what Unity Catalog already reports as
        # masked, {table: {column, ...}}. A CTAS copies the SHAPE and not the masks, so
        # "did the loader put them back" is a claim about the RUN, not about a string in
        # the file -- and it has to be answerable in both directions.
        self.masks_applied: list = []
        self.already_masked: dict = {}
        # The order of the three statements that matter, per table: create, then every
        # mask, then the insert. A mask issued after the insert protects nothing that has
        # not already been written.
        self.ops: dict = {}

    def _op(self, table, name):
        self.ops.setdefault(table, []).append(name)

    def sql(self, text):
        t = " ".join(text.split())
        _m = _FQ3.search(t)
        target = _m.group(1) if _m else ""
        if t.startswith("WITH ambiguity_payload AS"):
            # RECORDED, not just answered: Task 3's probe is now GATED on the two
            # counts main() already has, so "was it asked at all" is itself a
            # claim the checks below have to be able to red in both directions.
            self.probes.append(target)
            return _FakeResult(self.ambiguous_rows.get(target, []))
        if t.startswith("SELECT view_definition FROM"):
            _name = re.search(r"table_name = '([^']*)'", t).group(1)
            if _name in self.existing_views:
                return _FakeResult([{"view_definition": self.existing_views[_name]}])
            return _FakeResult([])
        if t.startswith("CREATE TABLE IF NOT EXISTS"):
            self._op(target, "create")
            return None
        if t.startswith("ALTER TABLE") and "SET MASK" in t:
            self._op(target, "mask")
            self.masks_applied.append(
                (target, re.search(r"ALTER COLUMN `([^`]+)`", t).group(1)))
            return None
        if t.startswith("SELECT column_name FROM"):
            # information_schema.column_masks. Rows carry .asDict(), as pyspark's Row
            # does and as load_satellites.masked_columns() reads them -- a plain dict
            # would make the loader's own reader raise, and it SWALLOWS that exception
            # (a missing view is not a reason to stop), so the fake would then be
            # answering "nothing is masked" for the wrong reason.
            _tbl = re.search(r"table_name = '([^']*)'", t).group(1)
            return _FakeResult([types.SimpleNamespace(asDict=lambda c=c: {
                "column_name": c}) for c in sorted(self.already_masked.get(_tbl, ()))])
        if t.startswith("CREATE OR REPLACE VIEW"):
            self.views_created.append(target)
            return None
        if t.startswith("INSERT INTO"):
            _vals = re.search(r"VALUES \('([^']*)',\s*(?:NULL|'[^']*'),\s*'([^']*)'", t)
            if "aud_table_load" in target:
                self.aud_load.append(_vals.groups())
                return None
            if "aud_table_discard" in target:
                _d = re.search(r"VALUES \('([^']*)',\s*'([^']*)'", t)
                self.aud_discard.append(_d.groups())
                return None
            # the vault insert: the anti-join lands the distinct keys, and a second pass
            # lands nothing more. This is the half that IS already idempotent.
            self._op(target, "insert")
            self.hub_rows[target] = self.distinct
            return None
        if "aud_table_load" in target and "WHERE job_run_id" in t:
            _r = re.search(r"job_run_id = '([^']*)'", t).group(1)
            _tb = re.search(r"table_name = '([^']*)'", t).group(1)
            return _FakeResult([{"n": self.aud_load.count((_r, _tb))}])
        if t.startswith("SELECT count(*) AS n, count(DISTINCT"):
            _n = self.hub_rows.get(target, 0)
            return _FakeResult([{"n": _n, "d": _n}])
        if t.startswith("SELECT count(DISTINCT"):
            return _FakeResult([{"d": self.distinct}])
        if t.startswith("SELECT count(*) AS n FROM"):
            return _FakeResult([{"n": self.staged if target.startswith("stg_")
                                 else self.hub_rows.get(target, 0)}])
        raise AssertionError(f"the fake was asked an unexpected query: {t[:90]!r}")


_lh_spec = _ilu2.spec_from_file_location("lh_mod", ROOT / "checks" / "load_hubs.py")
_lh_mod = _ilu2.module_from_spec(_lh_spec)
_lh_spec.loader.exec_module(_lh_mod)


# THE LAKE THE LOADER IS RUN AS, taken from databricks.yml rather than invented: the
# loader applies a mask only for a binding this lake LOADS, so an active-source list is
# part of the run, not decoration. usnc_tds is the target this branch deploys to.
_LH_ACTIVE_SPEC = (yaml.safe_load((ROOT / "databricks.yml").read_text(encoding="utf-8"))
                   ["targets"]["usnc_tds"]["variables"]["active_sources"])


def _run_hub_loader(fake, run_id, active_sources=_LH_ACTIVE_SPEC):
    _saved_argv, _saved_session = sys.argv, getattr(_stub_sql, "SparkSession", None)
    _stub_sql.SparkSession = types.SimpleNamespace(
        builder=types.SimpleNamespace(getOrCreate=lambda: fake))
    sys.argv = ["load_hubs.py", "--catalog", "c", "--schema", "raw_vault",
                "--active-sources", active_sources,
                "--control-schema", "control", "--job-run-id", run_id]
    _buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(_buf):
            rc = _lh_mod.main()
    finally:
        sys.argv, _stub_sql.SparkSession = _saved_argv, _saved_session
    return rc, _buf.getvalue()


