class _CtGateGrainSpark:
    """Answers check_uniqueness's two Spark calls and records the exact GROUP BY key it
    computed -- so the grain can be READ OFF THE GATE'S ACTUAL CODE PATH (check_uniqueness,
    loaded from checks/append_only_check.py above as _ct_aom) rather than re-derived by
    hand in this test. If the gate's satellite rule ever changes, the SQL it issues
    changes, and so does what this reads -- a hand-copied restatement would not have
    noticed such a change.
    """

    def __init__(self, columns):
        self._columns = list(columns)
        self.captured_key = None

    def table(self, _fq):
        return types.SimpleNamespace(
            schema=types.SimpleNamespace(
                fields=[types.SimpleNamespace(name=c) for c in self._columns]))

    def sql(self, text):
        _m = re.search(r"\(SELECT (.+?) FROM", text)
        if _m:
            self.captured_key = [c.strip() for c in _m.group(1).split(",")]
        return types.SimpleNamespace(collect=lambda: [{"n": 0}])


def _ct_gate_grain(table, columns):
    """The grain check_uniqueness ACTUALLY computes for `table`, read off its SQL."""
    fake = _CtGateGrainSpark(columns)
    _ct_aom.check_uniqueness(fake, f"`c`.`s`.`{table}`", table)
    return fake.captured_key


