def _ec_binding_cols(entity, src):
    """The projected column set of ONE physical table, straight from factory._projection
    for THAT binding -- the authority the emitter must agree with, not a restatement."""
    from accelerator import factory as _f
    return {c for c, _k, _v in _f._projection(
        entity, src if src is not None else entity.sources[0])}


