_q_cov = [d for d in _q_ds if d["name"].startswith("ds_coverage")]
check("every coverage dataset explodes generated_tables -- meta_vault_model.table_name is "
      "base_table, ONE ROW PER ENTITY, and would silently undercount every multi-source "
      "satellite",
      _q_cov and all("explode(generated_tables)" in " ".join(d["queryLines"])
                     for d in _q_cov),
      "a coverage dataset joins on meta_vault_model.table_name, which is base_table and "
      "carries no source suffix, so e.dataset can never match for a multi-source "
      "satellite and those tables read 'not evaluated' for ever")


def _q_table_refs(query_lines: list[str]) -> list[str]:
    """Every table named after a FROM or JOIN, minus this query's own CTE aliases.

    CASE-INSENSITIVE, and that matters: SQL keywords are case-free, so a lowercase
    `from governance.pipeline_event_log` named a table the exclusivity check below never
    saw. It failed OPEN -- the one direction a containment gate must not fail.
    """
    sql = " ".join(query_lines)
    cte_names = set(re.findall(r"(\w+)\s+AS\s*\(", sql, re.IGNORECASE))
    refs = re.findall(r"\b(?:FROM|JOIN)\s+([A-Za-z_][A-Za-z0-9_.]*)", sql, re.IGNORECASE)
    return [ref for ref in refs if ref not in cte_names]


_q_allowed_refs = set(quality.CONTROL_TABLES) | {"governance.meta_vault_model"}
_q_stray_refs = [(d["name"], ref) for d in _q_ds for ref in _q_table_refs(d["queryLines"])
                 if ref not in _q_allowed_refs]
check("every dataset queries only tables quality.CONTROL_TABLES names",
      not _q_stray_refs,
      f"{_q_stray_refs} reference a table outside CONTROL_TABLES and meta_vault_model -- "
      "containment alone (\"mentions at least one control table\") is not exclusivity")

_q_div = [d["name"] for d in _q_ds
          if "/" in " ".join(d["queryLines"])
          and quality.RATE_GUARD not in " ".join(d["queryLines"])]
check("every dataset computing a rate uses RATE_GUARD -- no bare division",
      not _q_div,
      f"{_q_div} divide without the guard; a zero denominator would render a rate over "
      "nothing, which is the false-confidence failure the spec exists to prevent")

_q_tiles = quality.tiles()
_q_tile_ds = {t["dataset"] for t in _q_tiles}
check("every tile references a dataset that exists",
      _q_tile_ds <= set(_q_names),
      f"tiles reference {sorted(_q_tile_ds - set(_q_names))} which no dataset defines")

# --------------------------------------------------------------------------- #
# SPEC 3, "IN THOSE WORDS", AND WHY RATE_GUARD IS NOT THE DEFENCE.
#
# RATE_GUARD only makes the zero-denominator branch yield NULL. Its own docstring says a
# NULL formatted as a percentage "reads as 'no problem' to a business user" -- so the guard
# converts a division error into a blank cell, and a blank cell is exactly the false
# confidence 2 describes. The ACTUAL defence is the adjacent literal `not evaluated`,
# which 3 requires in those words and 8 calls "the one to get right".
#
# Nothing asserted it, and two mutations left every check green: dropping `state` from
# w_accept_rate's fields, and renaming the literal to 'n/a' in both datasets. The three
# checks below close the whole path -- the dataset emits the words, the tile renders the
# column, and (in verify_repo.py) the committed artefact carries them.
#
# THE LITERAL IS HARDCODED HERE ON PURPOSE. If it were imported from quality.py as a
# constant shared with the SQL, renaming that constant would rename both the artefact and
# the assertion, and the check could never fail. An independent spelling is the point.
_Q_NOT_EVALUATED = "not evaluated"
# THE COVERAGE PATH USES ITS OWN WORD, and that is deliberate. 'not evaluated' is the RATE
# vocabulary: section 3 requires it where a denominator is zero, because a NULL rate would
# read as "no problem". Coverage is a different statement -- whether a rule EXISTS -- and
# reusing 'not evaluated' for it overloaded one phrase across two meanings. Measured 27 Aug:
# expectations evaluate rows as they ARRIVE, so declaring a rule validates nothing already
# landed, and the vault cannot be reprocessed (delta.appendOnly refuses the refresh). When the
# first four rules were declared, the tables they name already held rows carrying the
# violations those rules describe. 'covered' or 'not evaluated' would both have read as
# "checked" and been wrong for every row predating its rule.
_Q_NO_RULE = "no rule"
# The alias a `not evaluated` literal is exposed under: '... not evaluated' ... END AS <col>.
# Non-greedy so a later END AS in the same query cannot be captured instead.
_q_state_re = re.compile(rf"'{_Q_NOT_EVALUATED}'.*?END\s+AS\s+(\w+)",
                         re.DOTALL | re.IGNORECASE)


def _q_state_columns(dataset: dict) -> list[str]:
    """The column aliases in this dataset that carry the literal `not evaluated`."""
    return _q_state_re.findall(" ".join(dataset.get("queryLines") or []))


_q_ds_by_name = {d["name"]: d for d in _q_ds}
_q_rate_ds = [d for d in _q_ds if "/" in " ".join(d["queryLines"])]
_q_rate_no_state = [d["name"] for d in _q_rate_ds if not _q_state_columns(d)]
check("every dataset that divides also emits a column carrying the literal "
      "'not evaluated' -- RATE_GUARD yields only NULL, which is not an explanation",
      _q_rate_ds and not _q_rate_no_state,
      f"{_q_rate_no_state} compute a rate with no 'not evaluated' column beside it "
      f"(examined {len(_q_rate_ds)} dividing dataset(s)). RATE_GUARD turns a zero "
      f"denominator into NULL, and a NULL formatted as a percentage reads as 'no problem'. "
      f"Spec 3 requires the words 'not evaluated', and 8 calls this the one to get right")

_q_state_tiles = [t["name"] for t in _q_tiles
                  if _q_state_columns(_q_ds_by_name.get(t["dataset"], {}))]
_q_state_hidden = [(t["name"], _q_state_columns(_q_ds_by_name[t["dataset"]]))
                   for t in _q_tiles
                   if t["dataset"] in _q_ds_by_name
                   and _q_state_columns(_q_ds_by_name[t["dataset"]])
                   and not set(_q_state_columns(_q_ds_by_name[t["dataset"]]))
                   & set(t["fields"])]
check("every tile whose dataset carries a 'not evaluated' column RENDERS that column -- "
      "an explanation that stays in the dataset never reaches the reader",
      _q_state_tiles and not _q_state_hidden,
      f"{_q_state_hidden} read a dataset that explains its own blank cells and then omit "
      f"the explaining column from `fields` (examined {len(_q_state_tiles)} tile(s) whose "
      f"dataset carries one). The tile would render a NULL rate with nothing beside it "
      f"saying why -- indistinguishable from a rate of nothing going wrong")

# THE HEADLINE TILE IS THE ONE PLACE THE TWO CHECKS ABOVE CANNOT SEE, and section 8 calls
# this requirement "the one to get right". Both of them are reached only through a dataset
# that DIVIDES: _q_rate_ds is keyed on "/" appearing in the SQL, and _q_state_tiles is
# keyed on a dataset that ALREADY carries the literal. ds_coverage contains no division, so
# deleting its `CASE WHEN count(e.rule_name) = 0 THEN 'not evaluated'` branch AND dropping
# coverage_state from w_coverage_table's fields left all three of them green -- on the tile
# section 3 makes the headline. Removing the property removed the checks' own reason to
# look at it: a scoped condition that derives its scope from the thing it is policing.
#
# So these two key on the COVERAGE DATASETS BY NAME, unconditionally. ds_coverage_summary
# is excluded because it is the single-row counter: it reports a COUNT of not-evaluated
# tables (tables_not_evaluated) rather than a per-row state literal, and demanding the
# literal of it would be demanding the wrong shape. SINGLE_ROW_DATASETS is the existing
# authority for that distinction, so the split is not a second list to keep in step.
_q_cov_rowwise = [d for d in _q_cov if d["name"] not in quality.SINGLE_ROW_DATASETS]
_q_cov_state_re = re.compile(rf"'{_Q_NO_RULE}'.*?END\s+AS\s+(\w+)", re.S | re.I)


def _q_cov_state_columns(dataset) -> list:
    """The column a coverage dataset exposes its no-rule state under."""
    return _q_cov_state_re.findall(" ".join(dataset["queryLines"]))


_q_cov_no_state = [d["name"] for d in _q_cov_rowwise if not _q_cov_state_columns(d)]
check("every PER-TABLE coverage dataset carries the literal 'no rule' -- asserted BY NAME, "
      "so it holds whether or not the coverage SQL happens to divide",
      _q_cov and _q_cov_rowwise and not _q_cov_no_state,
      f"{_q_cov_no_state} are per-table coverage datasets with no 'no rule' literal "
      f"(examined {len(_q_cov_rowwise)} of {len(_q_cov)} coverage datasets; the rest are "
      f"single-row counters). Coverage is the HEADLINE metric of section 3 and it has no "
      f"division in it, so the rate-scoped checks above never reach it -- a table with no "
      f"declared rule would render a bare count of 0, indistinguishable from a table whose "
      f"rules all passed")

_q_cov_names = {d["name"] for d in _q_cov_rowwise}
_q_cov_tiles = [t for t in _q_tiles if t["dataset"] in _q_cov_names]
_q_cov_tile_hidden = [(t["name"], _q_cov_state_columns(_q_ds_by_name[t["dataset"]]))
                      for t in _q_cov_tiles
                      if not set(_q_cov_state_columns(_q_ds_by_name[t["dataset"]]))
                      & set(t["fields"])]
check("every tile reading a per-table coverage dataset RENDERS its 'no rule' column "
      "-- the headline tile above all",
      _q_cov_names and _q_cov_tiles and not _q_cov_tile_hidden,
      f"{_q_cov_tile_hidden} read a coverage dataset and omit its state column from "
      f"`fields` (examined {len(_q_cov_tiles)} tile(s) over {sorted(_q_cov_names)}). An "
      f"empty column list in that report means the dataset has no state column either, so "
      f"deleting the literal and dropping the column fails BOTH of these rather than "
      f"quietly removing the requirement")


# D1: meta_vault_model is in the GOVERNANCE schema while dataset_schema pins the default to
# CONTROL, so a bare reference resolves to a table that does not exist.
_q_mvm_bare = _q_sql.replace("governance.meta_vault_model", "")
check("meta_vault_model is always schema-qualified -- it lives in governance while "
      "dataset_schema pins the default to control",
      "meta_vault_model" not in _q_mvm_bare,
      "a bare meta_vault_model reference resolves to control.meta_vault_model, which does "
      "not exist; the coverage tile would fail at view time in front of a user")

# D2: a counter over a multi-row dataset renders an arbitrary row under an aggregate title.
_q_counters = [t for t in quality.tiles() if t["widgetType"] == "counter"]
_q_bad_counter = [t["name"] for t in _q_counters
                  if t["dataset"] not in quality.SINGLE_ROW_DATASETS]
check("every counter tile reads a single-row dataset",
      not _q_bad_counter,
      f"{_q_bad_counter} read a multi-row dataset. A counter renders whichever row arrives "
      f"first, so the tile would show one arbitrary table's number under a title claiming "
      f"an aggregate -- confidently wrong, which is the failure this dashboard exists to "
      f"avoid")

check("the first tile is coverage -- the spec's headline metric",
      _q_tiles and "coverage" in _q_tiles[0]["name"],
      f"first tile is {_q_tiles[0]['name'] if _q_tiles else '(none)'}; the spec makes "
      "coverage the headline, not pass rate")

_q_pref = quality.datasets(table_prefix="tst_")
_q_pref_sql = " ".join(" ".join(d["queryLines"]) for d in _q_pref)
check("a table prefix reaches every control table reference",
      all(f"tst_{t}" in _q_pref_sql for t in quality.CONTROL_TABLES),
      "prefixing left a bare control table name; the synthetic dashboard would read the "
      "real audit")

