_ecc_stmts = _ag_statements(_ecc_rendered)
_ecc_not_create = [s.splitlines()[0][:60] for s in _ecc_stmts
                   if not s.lstrip().upper().startswith("CREATE ")]
# ASSERT WHAT THE STATEMENTS MEAN, NOT A RAW TOTAL. A bare `len(_ecc_stmts) == len(CORE)`
# broke the moment gold_ddl() correctly grew a CREATE SCHEMA statement (Fix 4: gold's
# generated DDL had none, so the day gold's catalog exists, applying it raises
# SCHEMA_NOT_FOUND on all three CREATE TABLEs) -- and it broke with a message claiming a
# CREATE TABLE had been dropped, sending the next reader hunting a semicolon defect that
# did not exist. Asserting the SCHEMA statement plus one CREATE TABLE per core table is
# what this check actually means, and a correct addition of the schema statement does not
# trip it.
_ecc_bz_rendered = _ag_render(_ecc.bronze_ddl(),
                             {"bronze_catalog": "X", "control_schema": "control"})
_ecc_bz_stmts = _ag_statements(_ecc_bz_rendered)
_ecc_bz_not_create = [x.splitlines()[0][:60] for x in _ecc_bz_stmts
                      if not x.lstrip().upper().startswith("CREATE ")]
check("bronze's DDL survives the REAL statement splitter -- one schema, one CREATE per "
      "declared table, nothing else",
      len(_ecc_bz_stmts) == 1 + len(_cs.tables_for("bronze"))
      and not _ecc_bz_not_create,
      f"got {len(_ecc_bz_stmts)} statement(s), non-CREATE fragments {_ecc_bz_not_create} -- a "
      f"semicolon inside a comment or a COMMENT literal cuts this file into pieces, which has "
      f"happened four times in this repo")

_ecc_schema_stmts = [s for s in _ecc_stmts if s.upper().startswith("CREATE SCHEMA")]
_ecc_table_stmts = [s for s in _ecc_stmts if s.upper().startswith("CREATE TABLE")]
check("gold's DDL survives the REAL statement splitter -- the schema, then one CREATE "
      "per table gold declares, nothing else",
      len(_ecc_stmts) == len(_ecc_schema_stmts) + len(_ecc_table_stmts)
      and len(_ecc_schema_stmts) == 1
      and len(_ecc_table_stmts) == len(_ecc_gold_tables)
      and not _ecc_not_create,
      f"{len(_ecc_stmts)} statement(s) total, {len(_ecc_schema_stmts)} CREATE SCHEMA and "
      f"{len(_ecc_table_stmts)} CREATE TABLE for {len(_ecc_gold_tables)} declared tables, "
      f"and these do "
      f"not begin with CREATE: {_ecc_not_create}. A semicolon anywhere in the file -- "
      f"including inside a comment -- is cut by apply_governance.statements() before "
      f"comments are stripped, which silently drops a CREATE TABLE while leaving the "
      f"statement COUNT unchanged")

_ecc_created = [s for s in _ecc_stmts if "CREATE TABLE" in s.upper()]
check("every table gold declares appears in exactly one split statement of its DDL, and "
      "its schema is created before any of them",
      bool(_ecc_gold_tables)
      and len(_ecc_created) == len(_ecc_gold_tables)
      and all(any(f".{t} (" in s for s in _ecc_created) for t in _ecc_gold_tables)
      and bool(_ecc_stmts) and _ecc_stmts[0].upper().startswith("CREATE SCHEMA"),
      f"{len(_ecc_created)} CREATE TABLE statement(s) for {sorted(_ecc_gold_tables)}, first "
      f"statement is {_ecc_stmts[0].splitlines()[0][:60] if _ecc_stmts else '<none>'!r} -- "
      f"a count alone is not enough, because the corrupting case produced the right count "
      f"with one table missing, and a CREATE TABLE run before its schema exists raises "
      f"SCHEMA_NOT_FOUND")

check("no line of gold's DDL carries a semicolon that is not a statement terminator",
      all(";" not in ln or ln.rstrip().endswith(";") for ln in _ecc_gold.splitlines()),
      "a semicolon mid-line -- in a comment or anywhere else -- is a split point the "
      "splitter takes before it strips comments")

_ecc_contract = _ecc.bronze_contract()

check("the bronze contract requires the core and the delivery manifest",
      set(_ecc_contract["tables"]) == set(_cs.tables_for("bronze")),
      f"contract names {sorted(_ecc_contract['tables'])} against "
      f"{sorted(_cs.tables_for('bronze'))}")

check("the bronze contract states what staged and accepted mean in BRONZE",
      _cs.STAGED_MEANING["bronze"] in json.dumps(_ecc_contract),
      "three layers share one column shape and three meanings; a contract that omits the "
      "meaning invites bronze's accepted being compared with silver's")

check("the bronze contract states the append-only split per table",
      all(_ecc_contract["tables"][t]["append_only"] is (t in _cs.APPEND_ONLY)
          for t in _ecc_contract["tables"]),
      "a conforming layer must get the split right, not set the property everywhere -- so the "
      "contract has to say which is which")

check("the bronze contract carries the invariant it must satisfy",
      "staged = accepted + sum(discarded)" in json.dumps(_ecc_contract),
      "the invariant is what makes the core worth mandating; a contract listing columns "
      "without it asks for a shape rather than a guarantee")

check("render() is deterministic and ends with exactly one newline",
      _ecc.render(_ecc.bronze_contract()) == _ecc.render(_ecc.bronze_contract())
      and _ecc.render(_ecc_contract).endswith("\n")
      and not _ecc.render(_ecc_contract).endswith("\n\n"),
      "an unstable render makes the no-op regeneration gate flap")


# --------------------------------------------------------------------------- #
print("\n[standard] the live control-schema conformance check")

import control_conformance_check as _ccc  # noqa: E402

_ccc_full = {t: set(c) for t, c in _cs.tables_for("bronze").items()}

check("conformance() is silent on a layer that matches the standard",
      _ccc.conformance("bronze", _ccc_full) == [],
      "a check that fires on a conforming layer gets suppressed")

check("conformance() reports an ABSENT table distinctly from a wrong-columns table",
      (len(_ccc.conformance("bronze", {})) >= 1
       and any("absent" in p.lower() for p in _ccc.conformance("bronze", {}))),
      "a layer that has built nothing and a layer that built it wrong need different "
      "answers -- one is 'start here', the other is 'you are close'")

_ccc_missing_col = "pipeline_update_id"
_ccc_wrong = {t: set(c) for t, c in _ccc_full.items()}
_ccc_wrong["aud_table_load"] = _ccc_wrong["aud_table_load"] - {_ccc_missing_col}
# _ccc_missing_col is chosen SPECIFICALLY because it does not appear anywhere in the
# invariant sentence every missing-column message hard-codes ("staged = accepted +
# sum(discarded)"). A fixture that removed 'staged' would pass this check even if the
# message dropped the actual {missing} list entirely, because 'staged' is IN the
# boilerplate prose regardless of which column is missing -- proven by mutation: doing
# that (checks/control_conformance_check.py:63-64 -> f"{table} is missing columns.")
# left the whole suite GREEN. Asserting on str(missing) -- the literal repr the message
# interpolates -- is what actually exercises the {missing} interpolation.
_ccc_expected_missing = str([_ccc_missing_col])
check("conformance() names the missing column, not just the table",
      any(_ccc_expected_missing in p for p in _ccc.conformance("bronze", _ccc_wrong)),
      f"expected the literal missing-column list {_ccc_expected_missing} in a problem "
      f"message; got {_ccc.conformance('bronze', _ccc_wrong)} -- an operator cannot act on "
      f"'aud_table_load is wrong'")

check("conformance() reports an extra column too",
      any("stray" in p for p in _ccc.conformance(
          "bronze", {**_ccc_full, "aud_load_run": _ccc_full["aud_load_run"] | {"stray"}})),
      "a column the standard does not name is drift in the other direction, and is governed "
      "by accident")

# tables_for() RAISES on an unknown layer, deliberately, so a typo cannot read as a layer
# that simply declares nothing extra. Asserted as a raise, not as a truthy expression: an
# earlier draft of this check read `... != [] or True`, which can never fail.
#
# THE MESSAGE, NOT JUST THE EXCEPTION TYPE -- same reasoning as the tables_for() check
# above: `{**CORE, **LAYER_TABLES[layer]}` raises a bare KeyError on its own even with the
# explanatory guard deleted, so asserting only "some KeyError happened" cannot see the
# guard's loss.
_ccc_raised = False
_ccc_exc_msg = ""
try:
    _ccc.conformance("silvr", _ccc_full)
except KeyError as _ccc_exc:
    _ccc_raised = True
    _ccc_exc_msg = str(_ccc_exc)
check("conformance() RAISES on an unknown layer, with a message explaining why",
      _ccc_raised and "is not a layer this standard covers" in _ccc_exc_msg,
      f"raised={_ccc_raised}, message={_ccc_exc_msg!r} -- a typo'd layer name returning a "
      f"result instead of raising is indistinguishable from a conforming one, and raising "
      f"an unexplained KeyError (which the bare dict lookup does on its own) is "
      f"indistinguishable from the guard having been deleted")

check("append_only_conformance() catches an audit table that is not append-only",
      any("aud_load_run" in p for p in _ccc.append_only_conformance(
          "bronze", {"ctl_delivery_manifest"})),
      "an audit that can be rewritten is an audit nobody can rely on")

check("append_only_conformance() catches a config table that IS append-only",
      any("ctl_delivery_manifest" in p for p in _ccc.append_only_conformance(
          "bronze", set(_cs.CORE) | {"ctl_delivery_manifest"})),
      "an append-only manifest means a wrong delivery count can never be corrected")

# THE FIXTURE IS DERIVED, NOT TYPED. It read `set(_cs.CORE)` until 28 September 2026 --
# "bronze's append-only tables" and "the core" were the same set only while bronze declared
# nothing append-only of its own, and ctl_etl_run broke that coincidence. A hand-listed
# fixture here does not just go stale, it goes stale as a FALSE RED on a correct split.
_ccc_bz_correct_split = {t for t in _cs.tables_for("bronze") if t in _cs.APPEND_ONLY}
check("append_only_conformance() is silent when the split is right",
      bool(_ccc_bz_correct_split)
      and _ccc.append_only_conformance("bronze", _ccc_bz_correct_split) == [],
      f"the correct split must not fire -- append-only in bronze is "
      f"{sorted(_ccc_bz_correct_split)}")

# RULING D6. The append-only MARKER decision used to be inlined in main() as a live
# DataFrame .where(...).count() over SHOW TBLPROPERTIES -- untestable offline, despite the
# module docstring's claim of parity with schema_grant_check.py's decision-function shape.
# append_only_tables_from_properties() extracts that decision onto already-collected rows,
# matching control_object_rows()'s has_marker computation there: main() now collects the live
# TBLPROPERTIES rows first and decides after, so the decision itself never touches Spark.
# SPEC SECTION 6 REQUIRES THE LITERAL `not instrumented`, "explicitly, in those words", and
# section 8 names it as a gate. The code was corrected from `NOT INSTRUMENTED` to the spec's
# wording -- and the scoped re-review then reverted that ONE WORD and found both suites still
# green, because nothing anywhere read the literal. Fifth instance on this branch of a stated
# guarantee exceeding its fixture, and it was in the fix for that very pattern. The literal is
# source text, so reading the source is the right instrument, not a proxy for a deployed thing.
# READ THE STRING LITERALS, NOT THE FILE TEXT. A first cut of this check scanned the raw source
# and went red at once: the module's own comment says A MISSING CATALOG IS THE SAME
# "NOT INSTRUMENTED" STATE, in caps as prose emphasis, which is fine. What section 6 constrains
# is the message the operator SEES. ast.walk skips comments for free.
_ni_strings = [_n.value for _n in ast.walk(ast.parse(
    (ROOT / "checks/control_conformance_check.py").read_text(encoding="utf-8")))
    if isinstance(_n, ast.Constant) and isinstance(_n.value, str)]
_ni_lower = [_s for _s in _ni_strings if "not instrumented" in _s]
_ni_upper = [_s for _s in _ni_strings if "NOT INSTRUMENTED" in _s]
check("the not-instrumented message uses spec section 6's literal, in those words",
      _ni_lower and not _ni_upper,
      f"message strings with the spec's wording: {len(_ni_lower)}; with the forbidden "
      f"uppercase: {_ni_upper} -- section 6 says 'explicitly, in those words', so a check "
      f"written to the spec would not match the code")

check("append_only_tables_from_properties() counts a table whose marker is present",
      _ccc.append_only_tables_from_properties(
          [{"table": "aud_load_run", "key": "delta.appendOnly", "value": "true"}])
      == {"aud_load_run"},
      "a table marked delta.appendOnly = 'true' must be recognised as append-only")

check("append_only_tables_from_properties() ignores a table whose marker is absent",
      _ccc.append_only_tables_from_properties(
          [{"table": "ctl_delivery_manifest", "key": "some.other.property", "value": "true"}])
      == set(),
      "a table with no delta.appendOnly row at all must not be reported as append-only, even "
      "when some OTHER property on it happens to carry the value 'true'")

check("append_only_tables_from_properties() rejects the marker present with a non-'true' "
      "value",
      _ccc.append_only_tables_from_properties(
          [{"table": "ctl_quarantine_superseded", "key": "delta.appendOnly",
            "value": "false"}])
      == set(),
      "the live filter this replaces matched value = 'true' exactly, case-sensitively -- a "
      "property merely PRESENT with a different value must not count, or a table with "
      "delta.appendOnly = 'false' would be reported as compliant")

# THE CASE VARIANT SPECIFICALLY. The check above says "case-sensitively" but proves no such
# thing: its fixture is 'false', which is rejected by an exact match and by a case-insensitive
# one alike, so it cannot tell the two apart. Measured -- widening the comparison to
# r["value"].lower() == "true" left the whole suite GREEN. The docstring names 'True' and 'TRUE'
# as values that must NOT count, so one of them has to appear in a fixture or that sentence is
# asserted by nothing.
check("append_only_tables_from_properties() rejects a CASE VARIANT of 'true'",
      _ccc.append_only_tables_from_properties(
          [{"table": "aud_table_load", "key": "delta.appendOnly", "value": "True"}])
      == set(),
      "Spark SQL's value = 'true' is case-sensitive, so 'True' does not mark a table "
      "append-only in the lake; a Python-side comparison that lowercases first would report a "
      "table as compliant that the live filter never matched")

