_ii = (ROOT / "checks" / "invoice_issue.py").read_text(encoding="utf-8")


def _ii_try(fn):
    """fn()'s result, or the reason it raised.

    EVERY CALL INTO invoice_issue BELOW GOES THROUGH THIS. An exception raised inside a
    check's condition escapes check() and aborts the whole suite, reporting every later
    check as absent rather than failing one -- so a builder that raises returns a string
    that no comparison below can satisfy, and the check goes red with the reason in it.
    """
    try:
        return fn()
    except Exception as exc:  # noqa: BLE001 - reported, not swallowed
        return f"<unevaluable: {type(exc).__name__}: {exc}>"


def _ii_run(argv: list[str]) -> tuple[int, str]:
    """invoice_issue.main() under a fake argv, with stdout captured.

    BaseException, not Exception: argparse exits via SystemExit, and a run that argparse
    refuses is exactly what the parameter checks below assert. Returning 99 keeps that
    distinguishable from main()'s own 0 and 1.
    """
    _saved = sys.argv
    _buf = io.StringIO()
    try:
        sys.argv = ["invoice_issue.py"] + argv
        with contextlib.redirect_stdout(_buf):
            _rc = gi.main()
    except BaseException as exc:  # noqa: BLE001 - reported, not swallowed
        return 99, f"{_buf.getvalue()}\nraised {type(exc).__name__}: {exc}"
    finally:
        sys.argv = _saved
    return _rc, _buf.getvalue()


