class _FakePublishSpark:
    """Answers exactly the queries checks/publish_stable_views.py issues: a read of
    information_schema.views, a CREATE OR REPLACE VIEW, and the aud_table_load
    existence-check/insert pair -- nothing else, because this task writes no row into
    any vault table (R3's own reasoning: staged=0, accepted=0, no vault INSERT at all).
    An unrecognised statement RAISES, matching _FakeHubSpark's own stance: a fake that
    silently answers "nothing" would let this pass having exercised nothing.
    """

    def __init__(self):
        self.views_created: list = []
        self.aud_load: list = []
        self.existing_views: dict = {}

    def sql(self, text):
        t = " ".join(text.split())
        _m = _FQ3.search(t)
        target = _m.group(1) if _m else ""
        if t.startswith("SELECT view_definition FROM"):
            _name = re.search(r"table_name = '([^']*)'", t).group(1)
            if _name in self.existing_views:
                return _FakeResult([{"view_definition": self.existing_views[_name]}])
            return _FakeResult([])
        if t.startswith("CREATE OR REPLACE VIEW"):
            self.views_created.append(target)
            return None
        if t.startswith("INSERT INTO") and "aud_table_load" in target:
            _vals = re.search(r"VALUES \('([^']*)',\s*(?:NULL|'[^']*'),\s*'([^']*)'", t)
            self.aud_load.append(_vals.groups())
            return None
        if "aud_table_load" in target and "WHERE job_run_id" in t:
            _r = re.search(r"job_run_id = '([^']*)'", t).group(1)
            _tb = re.search(r"table_name = '([^']*)'", t).group(1)
            return _FakeResult([{"n": self.aud_load.count((_r, _tb))}])
        raise AssertionError(f"the fake was asked an unexpected query: {t[:90]!r}")


def _run_publish_stable_views(fake, run_id, active_sources=""):
    _saved_argv = sys.argv
    _saved_session = getattr(_stub_sql, "SparkSession", None)
    _stub_sql.SparkSession = types.SimpleNamespace(
        builder=types.SimpleNamespace(getOrCreate=lambda: fake))
    sys.argv = ["publish_stable_views.py", "--catalog", "c", "--schema", "raw_vault",
                "--control-schema", "control", "--job-run-id", run_id,
                "--active-sources", active_sources]
    _buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(_buf):
            rc = _psv_mod.main()
    finally:
        sys.argv, _stub_sql.SparkSession = _saved_argv, _saved_session
    return rc, _buf.getvalue()


# THIS TASK HAS NO SCOPE AGAINST THE REAL MODEL SINCE 29 SEPTEMBER, and its behaviour is
# still worth proving.
#
# PIPELINE_OWNED_KINDS is naming.GENERATABLE minus naming.STAGED_KINDS, and staging every
# keyed kind emptied it. Run end-to-end against the real model as written, every check
# below would pass over zero tables and assert nothing -- and the emptiness would be
# indistinguishable from the task being broken. So the runs are made with the LINK-LIKE
# kinds temporarily UN-staged, which is the only configuration in which this task owns
# anything at all; it is the same idiom the DEF-52 block above uses for the _v1 views, for
# the same reason.
#
# THE MODULE IS RE-EXECUTED UNDER THE PATCH, because PIPELINE_OWNED_KINDS is computed once
# at import. Patching naming alone would leave the module's own copy empty and give a
# green run over nothing, which is precisely the mirrored-oracle failure this file has
# been bitten by before. Restored, and re-executed again, in `finally`.
#
# The EMPTY-scope branch -- "GATE NOT EVALUATED ... no pipeline-owned kind is declared",
# exit 1 -- is a separate property of the real configuration and is deliberately not
# asserted here.
_psv_staged_save = naming.STAGED_KINDS
try:
    naming.STAGED_KINDS = frozenset(k for k in naming.STAGED_KINDS
                                    if k not in naming.LINK_KINDS)
    _psv_spec.loader.exec_module(_psv_mod)
    _psv_u_kinds = frozenset(_psv_mod.PIPELINE_OWNED_KINDS)
    _psv_u_entities = _psv_mod.pipeline_owned_entities(model)
    _psv_expected_stable = {naming.stable(t) for e in _psv_u_entities
                            for _s, t in e.tables()}
    _psv_physical_by_stable = {naming.stable(t): t for e in _psv_u_entities
                               for _s, t in e.tables()}
    _psv_fake = _FakePublishSpark()
    _psv_rc1, _psv_out1 = _run_publish_stable_views(_psv_fake, "PSV_RUN1")
    _psv_rc2, _psv_out2 = _run_publish_stable_views(_psv_fake, "PSV_RUN1")
    _psv_rc3, _psv_out3 = _run_publish_stable_views(_psv_fake, "PSV_RUN2")

    # F2, for this task too: a stable view that already points elsewhere is LEFT ALONE,
    # not repointed -- exactly the same rule load_hubs.py and load_satellites.py obey,
    # proven here because this task calls the SAME shared function, not a fresh
    # implementation of the same idea that could get the "elsewhere" branch wrong
    # independently.
    _psv_target_stable, _psv_other_stable = sorted(_psv_expected_stable)[:2]
    _psv_elsewhere_fake = _FakePublishSpark()
    _psv_elsewhere_fake.existing_views[_psv_target_stable] = (
        f"SELECT * FROM `c`.`raw_vault`.`{_psv_physical_by_stable[_psv_other_stable]}`")
    _psv_rc4, _psv_out4 = _run_publish_stable_views(
        _psv_elsewhere_fake, "PSV_RUN_F2")

    # Every pipeline-owned binding excluded: --active-sources names one real HUB binding
    # (accounting_journal/GP_US), which activates that ONE binding and nothing else -- so
    # every link/NHL/HAL binding is inactive, and this task must skip all of them rather
    # than fail, matching load_satellites.py's own "every satellite is inactive" outcome.
    _psv_inactive_fake = _FakePublishSpark()
    _psv_rc5, _psv_out5 = _run_publish_stable_views(
        _psv_inactive_fake, "PSV_RUN_INACTIVE",
        active_sources="accounting_journal/GP_US")
finally:
    naming.STAGED_KINDS = _psv_staged_save
    _psv_spec.loader.exec_module(_psv_mod)

check("the un-staged rehearsal actually gives this task something to own -- otherwise "
      "every check below passes over zero tables",
      _psv_u_kinds == naming.LINK_KINDS and len(_psv_expected_stable) > 1,
      f"kinds {sorted(_psv_u_kinds)}, {len(_psv_expected_stable)} stable name(s) -- "
      f"un-staging link/nhl/hal must hand exactly those three kinds back to this task")
check("and naming.STAGED_KINDS is restored afterwards, so nothing below reads a patched "
      "set",
      naming.STAGED_KINDS == _psv_staged_save
      and _psv_mod.PIPELINE_OWNED_KINDS == frozenset(naming.GENERATABLE)
      - naming.STAGED_KINDS,
      f"{sorted(naming.STAGED_KINDS)} / {sorted(_psv_mod.PIPELINE_OWNED_KINDS)}")
check("every pipeline-owned table's stable view is bootstrapped, under its "
      "UNVERSIONED name -- run end-to-end against the real model, not inferred from "
      "source text",
      _psv_rc1 == 0 and set(_psv_fake.views_created) == _psv_expected_stable,
      f"views created: {sorted(_psv_fake.views_created)} vs expected: "
      f"{sorted(_psv_expected_stable)}")
check("and one aud_table_load row is written per table, for the run that did it",
      len([r for r, _t in _psv_fake.aud_load if r == "PSV_RUN1"])
      == len(_psv_expected_stable),
      f"rows: {_psv_fake.aud_load} -- R3: without this row, assert_freshness and "
      f"cutover --gated-by-run stay silently blind to every pipeline-owned table")
check("a REPAIR RUN reusing the same job_run_id does not double-audit (DEF-56, same "
      "guard the loaders use)",
      _psv_rc2 == 0
      and len([r for r, _t in _psv_fake.aud_load if r == "PSV_RUN1"])
      == len(_psv_expected_stable),
      f"rows after a second run with the same run id: {_psv_fake.aud_load}")
check("a genuinely NEW job run id is audited normally -- the guard is per (run, table)",
      _psv_rc3 == 0
      and len([r for r, _t in _psv_fake.aud_load if r == "PSV_RUN2"])
      == len(_psv_expected_stable),
      f"rows: {_psv_fake.aud_load}")
check("a stable view that already points elsewhere is LEFT ALONE, never repointed",
      _psv_rc4 == 0 and _psv_target_stable not in _psv_elsewhere_fake.views_created,
      f"views_created={sorted(_psv_elsewhere_fake.views_created)} -- only "
      f"checks/cutover_vault_version.py may move a view that already points somewhere "
      f"else")
check("...and it is still audited -- 'left alone' is not the same as 'not considered "
      "this run'",
      len([r for r, _t in _psv_elsewhere_fake.aud_load if r == "PSV_RUN_F2"])
      == len(_psv_expected_stable),
      f"rows: {_psv_elsewhere_fake.aud_load}")
check("every pipeline-owned table inactive in this lake is NOT_EVALUATED, not FAILED "
      "-- a dormant lake is a correct outcome, and nothing is published or audited",
      _psv_rc5 == 0 and not _psv_inactive_fake.views_created
      and not _psv_inactive_fake.aud_load
      and "NOT EVALUATED" in _psv_out5,
      f"rc={_psv_rc5}, views_created={_psv_inactive_fake.views_created}, "
      f"aud_load={_psv_inactive_fake.aud_load}")

# --- mask_survival_check.py: the view is now examined too ------------------------------
_ms_src = (ROOT / "checks" / "mask_survival_check.py").read_text(encoding="utf-8")
check("mask survival examines the physical table AND the stable view",
      ".tables()" in _ms_src and ".stable_tables()" in _ms_src,
      "under parent decision D3 the column mask is the vault's only PII defence. The "
      "view is now what consumers read, so a missing or materialized view is the leak")
check("and it actually WIRES that into its per-entity sweep, not just defines a function "
      "nothing calls",
      "problems += stable_view_problems(" in _ms_src,
      "a defined-but-uncalled function asserts nothing about a live run")

import importlib.util as _ilu4  # noqa: E402
_ms_spec = _ilu4.spec_from_file_location("ms", ROOT / "checks" / "mask_survival_check.py")
_ms = _ilu4.module_from_spec(_ms_spec); _ms_spec.loader.exec_module(_ms)

# stable_view_problems() exercised directly, pure and Spark-free -- the same technique
# _ls.mask_statements() is exercised with above. DEF-53 already settled that a plain view
# needs no mask of its own; what this checks is EXISTENCE, which DEF-53 did not measure.
_svp_masked_sat = types.SimpleNamespace(
    kind="sat", masks=(("amount", "governance.mask_money"),))
check("a masked satellite whose stable view does NOT exist is a finding",
      len(_ms.stable_view_problems(
          _svp_masked_sat, "sat_probe_rev1", "sat_probe", set())) == 1,
      "consumers read sat_probe, never sat_probe_rev1 -- a missing view leaves the mask "
      "sitting, correctly but unreachably, on a table nobody is pointed at")
check("and reports NOTHING once the view exists as a plain view",
      _ms.stable_view_problems(
          _svp_masked_sat, "sat_probe_rev1", "sat_probe", {"sat_probe"}) == [],
      "DEF-53: a plain view carries no mask and needs none -- the base table's mask "
      "applies to anything selecting from it")
check("an entity declaring no masks needs no stable view asserted BY THIS FUNCTION",
      _ms.stable_view_problems(
          types.SimpleNamespace(kind="sat", masks=()), "sat_x_rev1", "sat_x", set())
      == [],
      "stable_view_problems() specifically grew out of DEF-53's mask-propagation "
      "argument and stays scoped to masked entities -- see "
      "stable_view_existence_problems() below for the unmasked case, F3")
# A MASKED NHL IS IN SCOPE SINCE 29 SEPTEMBER, and this check asserted the opposite.
#
# stable_view_problems() is scoped to naming.STAGED_KINDS because the two batch loaders
# are what publish a stable view, and until now a link, NHL or HAL was written straight
# into its physical table by the pipeline with no loader behind it -- so flagging its
# missing view would have failed a lake working exactly as built. Staging the keyed kinds
# gives every one of them a loader, so the absence of its view is a real finding again.
# The function itself did not change; its scope did, which is why the expectation flips
# here without a line moving in mask_survival_check.py.
check("a masked NHL is IN SCOPE for THIS function now that load_hubs.py publishes its "
      "stable view -- a missing view over masked data is a finding again",
      len(_ms.stable_view_problems(
          types.SimpleNamespace(kind="nhl",
                                masks=(("amount", "governance.mask_money"),)),
          "nhl_x_rev1", "nhl_x", set())) == 1,
      "an NHL is staged now, so checks/load_hubs.py publishes nhl_x after loading "
      "nhl_x_rev1; a consumer reading nhl_x gets TABLE_OR_VIEW_NOT_FOUND while the mask "
      "sits, correctly but unreachably, on a table nobody is pointed at")
check("...and reports nothing once that view exists as a plain view",
      _ms.stable_view_problems(
          types.SimpleNamespace(kind="nhl",
                                masks=(("amount", "governance.mask_money"),)),
          "nhl_x_rev1", "nhl_x", {"nhl_x"}) == [],
      "DEF-53: a plain view carries no mask and needs none")
# THE SCOPE TEST IS STILL A TEST, not a constant that now says yes to everything. Every
# GENERATABLE kind is staged, so the out-of-scope direction can only be shown with a kind
# that is not generatable at all -- `pit`, which is in naming.PREFIX, is platform-owned
# and has no loader. Without this the guard could be deleted outright and nothing would
# notice.
check("a kind naming.STAGED_KINDS does not cover is still OUT OF SCOPE for THIS "
      "function -- the guard is a scope test, not a formality",
      "pit" not in naming.STAGED_KINDS
      and _ms.stable_view_problems(
          types.SimpleNamespace(kind="pit",
                                masks=(("amount", "governance.mask_money"),)),
          "pit_x_rev1", "pit_x", set()) == [],
      "nothing in this repo loads or publishes a pit, so asserting its view's existence "
      "would fail a lake working exactly as built")

# --- F3: nothing asserted the stable view EXISTS for anything except "declares a mask
# AND is a staged kind" -- 2 tables in usnc_tds, measured. Every hub, every unmasked
